package br.edu.ifrn.sistemachamados.controller;
import br.edu.ifrn.sistemachamados.exception.DadosInvalidosException; import org.springframework.data.domain.*;
final class WebSupport {private WebSupport(){} static Pageable page(Integer page,Integer size,String[] sort){int p=page==null?0:page,s=size==null?10:size;if(p<0||s<1||s>50)throw new DadosInvalidosException("Parâmetros de paginação inválidos."); Sort so=Sort.unsorted();if(sort!=null)for(String x:sort){String[] a=x.split(",");if(a.length<1||a.length>2||a[0].isBlank())throw new DadosInvalidosException("Ordenação inválida.");try{so=so.and(Sort.by(a.length==2?Sort.Direction.fromString(a[1]):Sort.Direction.ASC,a[0]));}catch(Exception e){throw new DadosInvalidosException("Ordenação inválida.");}}return PageRequest.of(p,s,so);}}
